  "upgrade.trialHistoryNote": "Si está pagando Essentials y se cambia a Business, mantiene la misma cuenta de cliente y el mismo historial de prueba. Business no incluye una prueba adicional de siete días. Si sube el plan mientras su prueba original aún está activa, su fecha de finalización original no se restablece.",
  "upgrade.providerConfirmNote": "Los cambios de plan requieren la confirmación del proveedor de facturación. Cualquier diferencia de precio, prorrateo y fecha de entrada en vigor deben mostrarse antes de que apruebe el cambio. Una actualización no debe crear una segunda suscripción simultánea.",
  "upgrade.chargedThroughProviderNote": "Los cambios de plan se cobran a través del proveedor de facturación. Puede cancelar su suscripción desde esta página usando el botón Cancelar suscripción debajo de su plan actual, o desde Configuración. Cancelar detiene las renovaciones futuras al final de su período pagado; nunca finaliza su acceso de inmediato. Los espacios de trabajo gratuitos existentes no reciben cargos por ver estas opciones.",
