  "exports.eyebrow": "Datos",
  "exports.title": "Exportaciones y copias de seguridad",
  "exports.subtitleStart": "Las descargas siempre están limitadas a",
  "exports.subtitleRest": ". Cada archivo lleva la etiqueta del nombre del negocio y la fecha en que se creó.",
  "exports.createBusinessFirst": "Primero cree un negocio: las exportaciones pertenecen a un negocio, no a la aplicación.",
  "exports.lockedTitle": "Las exportaciones en CSV y Excel son una función del plan Business",
  "exports.lockedDesc": "Su espacio de trabajo está en el plan Essentials. Business agrega exportaciones en CSV y Excel, valuación de inventario, productos y personal ilimitados, proveedores, compras y paquetes.",
  "exports.seeBusiness": "Ver qué incluye Business",
  "exports.whatTheseAre": "Qué son estos archivos",
  "exports.about1": "Cada conjunto de datos viene como CSV o como un libro de Excel real (.xlsx): el libro completo de inventario es solo en Excel, con una hoja por conjunto de datos. Los archivos CSV se abren en Excel, Numbers, Google Sheets y la mayoría de las aplicaciones de inventario. El texto UTF-8, las comas entre comillas, los saltos de línea en las notas y los ceros iniciales en los códigos se conservan, y las celdas que comienzan como una fórmula se neutralizan para que la hoja de cálculo las abra como texto.",
  "exports.about2": "En los archivos de Excel, los SKU, UPC, ISBN y códigos de barras son celdas de texto, nunca en notación científica y nunca con ceros recortados, con anchos de columna, filtros de encabezado y formatos de moneda o cantidad aplicados. El libro completo de inventario mantiene los productos, los niveles de existencias, las ubicaciones y los movimientos en hojas separadas.",
  "exports.about3": "Las exportaciones muy grandes se detienen en 20,000 filas por conjunto de datos; cuando eso sucede, el nombre del archivo lo indica (truncated-20000), para que un archivo parcial nunca pase por completo.",
  "exports.about4": "Una copia de seguridad es una instantánea de sus datos, no una restauración con un clic. Restaurarla es un trabajo manual, con revisión previa, así que guarde el archivo en un lugar seguro: por ahora nada en la aplicación puede recrear un negocio eliminado a partir de ella. El código de la aplicación y las copias de seguridad de la plataforma Base44 se manejan por separado de estos archivos.",
  "exports.about5": "Las fotos y los archivos adjuntos se enumeran como sus enlaces almacenados: los archivos de imagen en sí no se incluyen en la descarga.",
  "exports.backupTitle": "Copia de seguridad completa",
  "exports.backupDesc": "Un solo archivo con los productos, ubicaciones, niveles de existencias, registro completo de movimientos, proveedores, compras, pedidos, devoluciones, conteos y publicaciones de este negocio, además de su configuración de perfil. Guárdelo en un lugar que usted controle.",
  "exports.backupIncludes1": "Productos, códigos, costos y notas",
  "exports.backupIncludes2": "Ubicaciones y cantidades por ubicación",
  "exports.backupIncludes3": "Cada movimiento, con autor y hora",
  "exports.backupIncludes4": "Compras, pedidos, devoluciones y conteos",
  "exports.buildingBackup": "Creando copia de seguridad…",
  "exports.backupJson": "Copia de seguridad (JSON)",
  "exports.excelSnapshot": "Instantánea de Excel",
  "exports.recordsDone": "{count} registros",
  "exports.backupDownloaded": "Copia de seguridad descargada",
  "exports.backupFailed": "La copia de seguridad falló",
  "exports.backupFailedDesc": "No se pudieron leer los datos del negocio. Inténtelo de nuevo.",
