  "import.eyebrow": "Datos",
  "import.title": "Centro de importación",
  "import.subtitleStart": "Tres operaciones de hoja de cálculo separadas, para que una corrección de precios nunca llegue como una recepción de existencias. Todo llega a",
  "import.subtitleRest": " únicamente, y no se escribe nada hasta que una prueba en seco haya pasado.",
  "import.createBusinessFirst": "Primero cree un negocio: los productos importados pertenecen a un negocio.",
  "import.createBusinessFirstShort": "Primero cree un negocio.",
  "import.whatEachDoes": "Qué hace cada operación",
  "import.createTitle": "Crear productos nuevos",
  "import.createDesc": "agrega filas que aún no están en el catálogo. Los SKU y códigos de barras duplicados que ya están en uso se omiten, y las existencias iniciales pueden llegar a una ubicación que usted elija como una recepción.",
  "import.updateTitle": "Actualizar productos existentes",
  "import.updateDesc": "coincide cada fila por SKU o ID de registro y muestra el valor anterior junto al nuevo propuesto. Las celdas en blanco dejan el valor guardado como está, a menos que pida que los espacios en blanco se borren, y las cantidades nunca se modifican.",
  "import.receiveModeTitle": "Recibir existencias",
  "import.receiveModeDesc": "agrega las cantidades que llegan a una ubicación y escribe una recepción en el registro de movimientos por cada línea. Cada lote queda marcado, para que la misma hoja no pueda recibirse dos veces.",
  "import.excelNote": "Los libros de Excel (.xlsx) se leen directamente: elija la hoja de cálculo y las columnas se asignan por usted. Los códigos se mantienen completos: un UPC guardado como texto conserva sus dígitos y ceros iniciales. Las filas que no se pueden importar se enumeran con un motivo",
  "import.excelNoteDownload": " y se pueden descargar como un archivo.",
  "import.excelNoteFix": ", para que pueda corregirlas e intentarlo de nuevo.",
  "import.matchColumns": "Asignar las columnas",
