  "print.supplierBlockedDesc": "Los documentos de proveedores van con el plan Business: proveedores, compras y órdenes de compra. Todo lo que tiene ahora sigue funcionando.",
  "print.seeBusiness": "Ver qué incluye Business",
  "print.nothingToPrint": "Aún no hay nada para imprimir",
  "print.pickOrderHint": "Elija una orden de compra de la lista para ver una vista previa del documento.",
  "print.pickCustomerOrderHint": "Elija un pedido de cliente de la lista para ver una vista previa del documento.",
  "print.pickReturnHint": "Elija una devolución registrada de la lista para ver una vista previa del documento.",
  "print.chooseStyleHint": "Elija un estilo y luego elija productos de la lista. La vista previa muestra exactamente lo que saldrá de la impresora.",
  "print.howToReach": "Cómo llegar a su impresora",
  "print.howIntro": "Esta aplicación se conecta a impresoras que ya son suyas: no es una impresora en sí misma. Hay cuatro maneras de llegar a una, y las etiquetas se imprimen en ambos planes por cualquiera de ellas. Los comprobantes de empaque, las órdenes de compra, los documentos de proveedores y los informes son solo del plan Business, sea cual sea la conexión.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Desde esta página, en Chrome o Edge de escritorio y en Chrome de Android: elija su impresora de etiquetas y las etiquetas irán directamente a ella. No funciona en Safari de iOS: en un iPhone, la impresión por Bluetooth viene con la aplicación móvil. Una impresora que solo entiende Zebra ZPL o el lenguaje propio de Brother no entenderá las etiquetas que envía esta página; eso se verifica contra impresoras reales antes de decir que funciona.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Instale la impresora en el Wi-Fi de su tienda y luego use el botón Imprimir: imprime a través de la impresora instalada en esta computadora, por la red de la tienda. En un iPhone, AirPrint está integrado: una impresora AirPrint en el mismo Wi-Fi simplemente aparece en la hoja de impresión, sin cable y sin necesidad de una aplicación, y la aplicación no necesita código específico de AirPrint. La impresora debe ser compatible con AirPrint (la mayoría de las nuevas lo son) y el teléfono y la impresora deben estar en el mismo Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Conecte la impresora a la red de su tienda con un cable Ethernet, instálela en la computadora e imprima con el botón Imprimir. Ethernet es una vía de escritorio y computadora: los iPhone no usan cables Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Conecte la impresora a la computadora con su cable y use el botón Imprimir: imprime a través de la impresora instalada allí. En un teléfono Android con un cable USB OTG, el botón USB de arriba se comunica directamente con la impresora. Los iPhone no pueden imprimir por USB directamente (no hay WebUSB allí), así que use Wi-Fi / AirPrint, o Bluetooth desde la aplicación móvil.",
  "print.howCordsLead": "Los cables aún sirven para los iPhone, con un paso de por medio.",
  "print.howCordsBody": "Una impresora USB conectada a la computadora de la tienda, o una impresora Ethernet conectada a la red, aparece en su iPhone por el Wi-Fi de la tienda (AirPrint / impresora compartida): los cables ponen la impresora en la red de forma sólida, y el teléfono llega a ella de forma inalámbrica.",
  "print.howOfflineLead": "Si se cae el internet,",
  "print.howOfflineBody": "las etiquetas y los documentos que ya están en esta página aún se imprimen: el botón Imprimir, el PDF de etiquetas, Bluetooth y USB no necesitan conexión. Lo que sí necesita internet es cargar la página y sus productos en primer lugar. El modo completamente sin conexión (trabajar en la aplicación sin ninguna conexión) es una construcción separada y más grande, y no se afirma aquí.",
