  "settings.cancelSubscription": "Cancelar suscripción",
  "settings.cancelTerms.appleLink": "Instrucciones de cancelación de Apple",
  "settings.cancelTerms.googlePlayLink": "Instrucciones de cancelación de Google Play",
  "settings.cancelTerms.graceTitle": "Después de que termine su periodo pagado — 15 días de gracia, luego eliminación:",
  "settings.cancelTerms.intro": "Estos son los términos para las suscripciones pagadas de Luminous StockHaven. La facturación de la suscripción del sitio web es a través de Stripe. Puede cancelar su suscripción usted mismo en cualquier momento con el botón Cancelar suscripción a continuación — no se necesita aprobación del personal. Las solicitudes de cancelación y reembolso también pueden gestionarse a través del contacto oficial de atención al cliente, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Puede cancelar su suscripción usted mismo en cualquier momento. No se requiere aprobación del personal. Las renovaciones futuras se detienen solo después de que el proveedor de facturación confirme la cancelación.",
  "settings.cancelTerms.noApprovalTitle": "Cancelar sin aprobación:",
  "settings.cancelTerms.paymentBody": "Para las pruebas pagadas, la prueba de siete días requiere un método de pago al registrarse. A menos que se cancele dentro del plazo de cancelación de la prueba correspondiente, el plan mensual seleccionado se cobrará automáticamente después de la prueba. El precio, la primera fecha de facturación y el plazo de cancelación específico del proveedor deben mostrarse durante el registro. La facturación de la prueba es a través de Stripe.",
  "settings.cancelTerms.paymentTitle": "Método de pago y renovación automática:",
  "settings.cancelTerms.remainingBody": "Si ya pagó un periodo de facturación, puede conservar el acceso hasta esa fecha verificada de pago hasta. La terminación anticipada requiere la confirmación adecuada del proveedor y cualquier gestión de reembolso aplicable. El acceso de la prueba gratuita termina según la fecha de terminación de la prueba confirmada por el proveedor.",
  "settings.cancelTerms.remainingTitle": "Acceso restante:",
  "settings.cancelTerms.storesBody": "Si alguna vez se suscribe a través de Google Play o la Apple App Store, su suscripción la factura y gestiona esa tienda. Es posible que deba cancelarla directamente en la sección de suscripciones de la misma cuenta de Google o Apple usada para suscribirse. Cancelar una suscripción independiente del sitio web, desinstalar esta aplicación o solicitar la eliminación de la cuenta de Luminous StockHaven no cancela automáticamente una suscripción facturada por una tienda. Revise su recibo de compra para confirmar quién le factura.",
  "settings.cancelTerms.storesTitle": "Suscripciones de Google Play y Apple App Store (si alguna vez se suscribe a través de una tienda):",
  "settings.cancelTerms.title": "Términos y condiciones de cancelación",
  "settings.cancelTerms.trialBody": "La prueba de siete días puede usarse solo una vez por cliente elegible. Cancelar una prueba o suscripción no otorga otra prueba; los clientes que regresan deben elegir una suscripción pagada.",
  "settings.cancelTerms.trialTitle": "Una prueba gratuita:",
  "settings.canceled.endsOn": "Esta suscripción está cancelada y termina el {date}. Conserva acceso completo hasta entonces.",
  "settings.delete.checking": "Comprobando si existe una solicitud de eliminación…",
  "settings.delete.description": "Solicitar la eliminación de su cuenta de inicio de sesión de Luminous StockHaven.",
  "settings.delete.dialogDescription": "Esto solicita una revisión de la eliminación de la cuenta. No elimina de inmediato su inicio de sesión ni su inventario, y no cancela ninguna suscripción de Stripe. Escriba {word} para confirmar que desea enviar la solicitud.",
  "settings.delete.dialogTitle": "Solicitar eliminación de la cuenta",
  "settings.delete.enterDelete": "Ingrese {word} para confirmar",
  "settings.delete.exportFirst": "Exporte su inventario primero si necesita conservar sus registros.",
  "settings.delete.intro": "Enviar una solicitud no elimina de inmediato su cuenta, negocios ni inventario. Las solicitudes se revisan por separado antes de que la eliminación pueda completarse. Esta solicitud no cancela una suscripción de Stripe ni detiene la facturación futura; la cancelación de la suscripción debe gestionarse por separado a través del proveedor de facturación.",
  "settings.delete.keepAccount": "Conservar la cuenta",
  "settings.delete.noExport": "Essentials no tiene exportación — anote todo lo que necesite antes de solicitar la eliminación.",
  "settings.delete.notDeleted": "Su cuenta y sus datos no han sido eliminados por esta solicitud. La facturación no ha sido cancelada.",
  "settings.delete.received": "Su solicitud de eliminación de cuenta ha sido recibida.",
  "settings.delete.requestButton": "Solicitar eliminación de la cuenta",
