  "settings.trial.cancelKeeps": "Cancelar durante su prueba conserva sus 7 días completos — el acceso termina el {date} y no se le cobrará.",
  "staff.access.noSeatBody": "Su cuenta no tiene un puesto de personal para este negocio, así que su inventario permanece cerrado. Pida al propietario que lo agregue en Personal y roles.",
  "staff.access.noSeatTitle": "Este negocio no está abierto a su cuenta",
  "staff.access.pendingBody": "Este negocio tiene una invitación para su correo electrónico que no ha sido activada. Pida al propietario que ponga el estado de su personal en activo. Nada aquí es visible hasta entonces.",
  "staff.access.pendingTitle": "Su invitación aún no está activa",
  "staff.access.signOut": "Cerrar sesión",
  "staff.access.suspendedBody": "Un administrador ha suspendido esta cuenta de personal para el negocio activo. Pídale que lo ponga de nuevo en activo y luego inicie sesión otra vez.",
  "staff.access.suspendedTitle": "Su acceso está en pausa",
  "staff.addFirst": "Agregar al primer miembro del personal",
  "staff.addMember": "Agregar miembro del personal",
  "staff.emptyBody": "Agregue a una persona, dele un rol y los permisos que lo acompañan, y se le invita por correo electrónico a iniciar sesión en este negocio.",
  "staff.emptyTitle": "Aún no hay personal",
  "staff.eyebrow": "Equipo",
  "staff.how.p1": "Cada miembro tiene un rol y su propia lista de permisos, así que puede partir de un rol y cambiar una sola cosa sin crear un rol nuevo. Editar un rol no reescribe a los miembros que ya están en él — abra un miembro para volver a aplicar los valores predeterminados de su rol.",
  "staff.how.p2": "Los roles personalizados son una función de Business: Essentials usa los cinco roles integrados (Propietario, Gerente, Empleado de inventario, Empleado de ventas, Visualizador).",
  "staff.how.p3": "Las invitaciones se envían por correo electrónico. Un miembro solo puede iniciar sesión una vez que acepta, y quitar a alguien de esta lista no elimina su cuenta de la aplicación.",
  "staff.how.p4": "Una tienda es la ubicación a la que está asignada una persona. Se registra en su tarjeta; lo que puede abrir sigue decidido por su rol y sus permisos.",
  "staff.how.p5": "Los permisos deciden qué puede abrir cada persona: los elementos del menú fuera de su rol se ocultan, y una dirección bloqueada muestra un aviso de “no está en su rol” en lugar de la página. Un cambio se aplica la próxima vez que esa persona carga la aplicación; suspender a un miembro lo bloquea por completo.",
  "staff.how.p6": "Los administradores pueden ver y cambiar todos los datos, gestionar los usuarios y roles de la aplicación, y nunca están limitados por un rol de personal. Alguien sin registro de personal — el propietario de un negocio nuevo — conserva acceso completo.",
  "staff.howTitle": "Cómo funcionan el personal y los roles",
