  "payroll.dd.savings": "Cuenta de ahorros",
  "payroll.dd.steps.body": "1. Necesita una cuenta bancaria comercial que pueda enviar pagos ACH. 2. Recopile un formulario de autorización firmado de cada miembro del equipo; un cheque anulado ayuda a verificar los números. 3. Envíe la nómina 2-3 días hábiles antes del día de pago para que el dinero llegue a tiempo. 4. La mayoría de los estados exige el consentimiento por escrito del miembro del equipo. Esta aplicación recopila los formularios y le guía por los pasos; el envío del dinero se hace a través de su propio banco.",
