  "workforce.unscheduledNote": "Hoy no hay turno programado, así que este tiempo se marcará como sin horario programado.",
  "workforce.inbox.help": "Eventos de fichaje, respuestas sobre días libres, tareas, recibos de pago y cambios de horario de su equipo, lo más reciente primero.",
  "workforce.messages.back": "Todas las conversaciones",
