  "rewards.status.redeemed": "Usada",
  "rewards.status.void": "Anulada",
  "rewards.subtitle": "Diga gracias con una recompensa: un porcentaje de descuento, una tarjeta de regalo o cualquier cosa que usted describa.",
  "rewards.title": "Recompensas e incentivos",
  "rewards.value.giftCard": "Tarjeta de regalo de {value}",
  "rewards.value.percentOff": "{percent} % de descuento en tienda",
  "rewards.void": "Anular",
  "rewards.voided": "Recompensa anulada.",
  "workforce.tab.rewards": "Recompensas",
  "training.lessons.mgr-give-rewards.step1": "Abra Equipo de trabajo y toque Recompensas. Elija al miembro del equipo y luego el tipo: un porcentaje de descuento en tienda, una tarjeta de regalo u otra cosa que describa con sus propias palabras.",
  "training.lessons.mgr-give-rewards.step2": "Dé a la recompensa un nombre corto y una nota si quiere. La persona recibe un aviso en su campana de inmediato, y la recompensa espera en sus Mis recompensas con su propio código.",
  "training.lessons.mgr-give-rewards.step3": "El límite, por diseño: usted recompensa SOLO al PERSONAL. No puede recompensarse a sí mismo ni a otro gerente; recompensar a un gerente es decisión del propietario, y la aplicación lo rechazará con claridad.",
  "training.lessons.mgr-give-rewards.step4": "En la caja, escriba el código que le muestra el miembro del equipo y márquelo como usado; cada código funciona una vez. Puede anular una recompensa que usted dio si los planes cambian; los regalos del propietario solo puede anularlos el propietario.",
  "training.lessons.mgr-give-rewards.title": "Dar recompensas a su personal",
  "training.lessons.owner-give-rewards.step1": "Las recompensas están en Equipo de trabajo, en la pestaña Recompensas, y son solo del plan Business: en Essentials, la pestaña muestra una puerta cerrada con llave, para que su equipo vea lo que ofrece el plan mayor.",
  "training.lessons.owner-give-rewards.step2": "Puede recompensar a CUALQUIERA del equipo: personal y gerentes por igual. Elija a la persona y luego el tipo: un porcentaje de descuento en tienda (cualquier porcentaje que elija), una tarjeta de regalo para cualquier lugar o cualquier incentivo que describa con sus propias palabras.",
  "training.lessons.owner-give-rewards.step3": "La recompensa llega con su propio código de un solo uso y hace sonar la campana de la persona. Ellos muestran el código en la caja; un propietario o gerente lo escribe para marcarlo como usado.",
  "training.lessons.owner-give-rewards.step4": "Un comprobante de recompensa impreso o compartido lleva solo el nombre de SU negocio, nunca el de la aplicación. Es el agradecimiento de su tienda, no un anuncio.",
  "training.lessons.owner-give-rewards.title": "Dar recompensas (plan Business)",
  "training.lessons.owner-rewards-oversight.step1": "Su gerente también puede dar recompensas: solo al personal. La aplicación rechaza que un gerente se recompense a sí mismo o a otro gerente; recompensar a un gerente es siempre decisión suya.",
  "training.lessons.owner-rewards-oversight.step2": "Usted ve cada recompensa del negocio en el Historial de recompensas: quién la dio, quién la recibió y si está lista, usada o anulada. Un gerente ve solo las recompensas que dio y las que recibió.",
  "training.lessons.owner-rewards-oversight.step3": "Puede anular cualquier recompensa, incluida una que haya dado su gerente. Un gerente puede anular sus propios regalos, pero nunca los suyos.",
  "training.lessons.owner-rewards-oversight.step4": "Cada código funciona exactamente una vez, y una recompensa anulada nunca puede usarse; el historial siempre muestra cómo terminó una recompensa.",
  "training.lessons.owner-rewards-oversight.title": "Supervisar las recompensas: lo que da su gerente",
  "training.lessons.staff-your-rewards.step1": "Cuando su gerente o el propietario le da una recompensa, su campana suena. Abra Equipo de trabajo y toque Recompensas para verla en Mis recompensas.",
  "training.lessons.staff-your-rewards.step2": "Cada recompensa tiene su propio código. Guárdelo para usted: quien muestra el código en la caja es quien usa la recompensa.",
  "training.lessons.staff-your-rewards.step3": "Para usarla, muestre el código cuando compre. La persona de la caja lo escribe y lo marca como usado; cada código funciona exactamente una vez.",
  "training.lessons.staff-your-rewards.step4": "Las recompensas son un gusto del plan Business. Si su tienda no está en Business, la pestaña Recompensas muestra en su lugar una puerta cerrada con llave: es el plan, no un error.",
  "training.lessons.staff-your-rewards.title": "Sus recompensas: encontrar su código y usarlo",
  "training.module.rewards": "Recompensas e incentivos",
